    htmlClientWidth: 900,
    htmlClientHeight: 600,
    htmlBCRLeft: 0,
    htmlBCRWidth: 890, // e.g. `html { margin-right: 10px }`
    htmlScrollLeft: 0,
    visualViewportWidth: 900,
  });

