  {
    boundary: 'layoutViewport',
    webkit: false,
    strategy: 'fixed',
    expected: {x: 0, y: 0, width: 800, height: 600},
  },
  {
    boundary: 'layoutViewport',
    webkit: true,
    strategy: 'absolute',
    expected: {x: -30, y: -20, width: 800, height: 600},
  },
  {
    boundary: 'layoutViewport',
    webkit: true,
